#include <cstdio>
#include <cstdlib>
#include <map>
#include "engine/gameplay/editor_frontend.hpp"
#include "tests/unit/force_inventory_fixture.hpp"
namespace {
using namespace gf;unsigned checks=0;void check(bool b,const char* why){++checks;if(!b){std::fprintf(stderr,"editor frontend: %s\n",why);std::abort();}}
struct Save final:ISaveBackend {std::map<u32,std::vector<u8>> data;std::array<unsigned,3> writes{};bool load(u32 n,std::vector<u8>& out)override{if(!data.contains(n))return false;out=data[n];return true;}SaveReadStatus read_slot(u32 n,std::vector<u8>& out)override{return load(n,out)?SaveReadStatus::Loaded:SaveReadStatus::Missing;}bool store(u32 n,const u8* b,std::size_t size)override{if(n>2)return false;data[n]={b,b+size};++writes[n];return true;}bool erase(u32 n)override{return data.erase(n)!=0;}};
ForceSpecificationCatalog spec(const ForceCatalog& c){std::vector<u8> b(26+c.entries().size()*138);store_be32(b.data(),0x47465344);store_be32(b.data()+4,1);store_be32(b.data()+8,c.fingerprint());store_be16(b.data()+12,u16(c.entries().size()));store_be16(b.data()+14,138);for(unsigned i=0;i<c.entries().size();++i){const auto at=26+i*138;store_be16(b.data()+at,c.entries()[i].model);store_be16(b.data()+at+2,c.entries()[i].number);b[at+8]=255;for(unsigned j=8;j<13;++j)b[at+5+j]=255;for(unsigned j=0;j<60;++j)store_be16(b.data()+at+18+2*j,100);}ForceSpecificationCatalog d;std::string error;check(d.load({b.data(),b.size()},c,&error),"metadata");return d;}
GamePadState pad(u32 b){GamePadState p;p.a=b&0x100;p.b=b&0x200;p.x=b&0x400;p.y=b&0x800;p.start=b&0x1000;p.dpad_up=b&8;p.dpad_down=b&4;p.dpad_left=b&1;p.dpad_right=b&2;p.r=b&0x20;return p;}
}
int main(){using namespace gf;auto catalog=force_inventory_fixture::catalog();auto data=spec(catalog);ForceInventory owner;check(owner.create(catalog),"owner");Save backend;ForceInventoryStore inventory_store(backend);OptionSettingsStore options(backend);CheatSettingsStore cheats(backend);check(inventory_store.load(catalog,&owner)==ForceInventoryLoad::Missing,"isolated save");ForceSupplement names;std::array<std::string,6> variants={"N","A","G","S","C","B"};std::array<std::string,10> digits;for(unsigned i=0;i<10;++i)digits[i]=std::to_string(i);std::string error;check(names.assign(catalog,{{0x1001,2}},"PART ",variants,digits,{"A","B"},&error),"names");MenuNavigationConfig nav;nav.repeat_limit=35;nav.repeat_restart=30;for(unsigned i=0;i<7;++i)nav.neighbor[i]={0,4,u8((i+6)%7),u8((i+1)%7)};EditorFrontend host;
    auto tick=[&](u32 bits=0,u32 editor=0){std::array<GamePadState,4> pads{};pads[0]=pad(bits);check(host.update(pads,{},bits&15,editor),"host callback");};
    for(unsigned item:{1u,2u,3u,5u,6u}){check(host.open(owner,names,data,inventory_store,options,cheats,nav,{0,1,3,1},item),"unported initial selection");tick(0x100);check(host.view()==EditorFrontendView::Unavailable,"modal opens");tick(0x100);check(host.view()==EditorFrontendView::Unavailable,"activation hold cannot dismiss");tick();tick(0x100);check(host.view()==EditorFrontendView::Main&&host.menu().selection()==item,"A returns same selection");tick(0x100);check(host.view()==EditorFrontendView::Main,"dismiss hold cannot reopen");tick();tick(8);check(host.menu().selection()==0,"navigation restored");}
    check(host.open(owner,names,data,inventory_store,options,cheats,nav,{0,1,3,1},0)&&host.configure_credits(2),"option entry");tick(0x100);tick();tick();check(host.transition().phase()==OptionTransitionPhase::UI,"source camera completed");tick(8);check(host.options().row()==9,"source ten rows retained");tick();tick(8);check(host.options().row()==8,"More replaces Staff Credits row");tick();tick(0x100);check(host.view()==EditorFrontendView::More&&host.more_row()==0,"More intermediate menu");tick(0x100);check(host.view()==EditorFrontendView::More,"held confirm cannot enter Cheats");tick();tick(0x100);check(host.view()==EditorFrontendView::Cheats,"same TV cheats");tick(0x100);check(host.cheats()==CheatSettings{},"held confirmation does not toggle");tick();tick(0x100);tick();tick(4);tick();tick(0x100);check(host.cheats()==CheatSettings{true,true},"enabled warehouse tools");tick();tick(4);tick();tick(0x100);check(host.cheats()==CheatSettings{true,true}&&host.cheat_row()==2,"battle placeholder cannot toggle");tick();tick(0x200);check(backend.writes[2]==1&&host.view()==EditorFrontendView::More&&host.more_row()==0,"cheat persistence and More return");tick(0x200);check(host.view()==EditorFrontendView::More,"held B cannot skip parent");tick();tick(4);tick();tick(0x100);check(host.view()==EditorFrontendView::CreditsDelay&&host.credits_delay()==2,"original credits preparation");tick(0x200);tick(0x200);check(host.view()==EditorFrontendView::Credits,"B during prep consumed");tick(0x200);check(host.view()==EditorFrontendView::Credits,"prep B cannot close credits");tick();tick(0x200);check(host.view()==EditorFrontendView::More&&host.more_row()==1,"credits B returns to More row1");tick();tick(0x100);tick();tick();check(host.view()==EditorFrontendView::Credits&&host.finish_credits()&&host.view()==EditorFrontendView::More,"natural credits end returns without saving");tick();tick(0x200);check(host.view()==EditorFrontendView::Option&&host.options().row()==8,"More B restores original row8");tick();tick(0x200);check(host.options().phase()==OptionMenuPhase::Saved&&backend.writes[1]==1,"option saved");tick();tick(0x100);tick();tick();check(host.view()==EditorFrontendView::Main,"option returns to main");tick();tick(4);tick();tick(0x100);check(host.view()==EditorFrontendView::Editor&&host.editor().cheats()==CheatSettings{true,true},"main carries selected cheat intent");tick();tick(0x20,0x20);check(host.editor().warehouse_tools(),"warehouse tools reachable");tick();tick(0x200,0x200);check(host.editor().view()==ForceEditorView::Grid,"warehouse back retains editor");tick();tick(0x1000,0x80);check(host.view()==EditorFrontendView::Main&&host.menu().selection()==4&&backend.writes[0]==1,"editor save returns same main seal");tick(0x1000);check(host.view()==EditorFrontendView::Main,"held Start cannot reopen");tick();tick(0x100);check(host.view()==EditorFrontendView::Editor&&host.editor().cheats()==CheatSettings{true,true},"fresh repeat entry retains cheat choices");
    check(host.open(owner,names,data,inventory_store,options,cheats,nav,{0,1,3,1},0),"radio-layout entry");tick(0x100);tick();tick();tick(8);tick();tick(8);tick();tick(0x100);tick();tick(0x100);check(host.view()==EditorFrontendView::Cheats&&host.cheats().warehouse_selector,"saved settings restored through More");tick();tick(2);check(!host.cheats().warehouse_selector,"right selects source OFF artwork");tick(2);check(!host.cheats().warehouse_selector&&host.sounds().empty(),"unchanged held OFF is silent");tick();tick(1);check(host.cheats().warehouse_selector,"left selects source ON artwork");tick();tick(1);check(host.cheats().warehouse_selector&&host.sounds().empty(),"already ON is silent");
    const auto settings_before=host.cheats();const auto revision_before=owner.revision();for(unsigned row=0;row<7;++row){tick();tick(0x800);check(host.view()==EditorFrontendView::CheatDetails&&host.cheat_row()==row,"Y opens selected details");tick(0x800);check(host.view()==EditorFrontendView::CheatDetails,"held Y stays in one popup");tick(4);check(host.cheat_row()==row&&host.cheats()==settings_before,"popup ignores navigation and cannot change cheat settings");tick();tick(row%2?0x200:0x100);check(host.view()==EditorFrontendView::Cheats&&host.cheat_row()==row,"A/B closes to same cheat row");tick(row%2?0x200:0x100);check(host.view()==EditorFrontendView::Cheats&&host.cheats()==settings_before,"dismiss hold cannot toggle or skip parent");tick();if(row<6){tick(4);check(host.cheat_row()==row+1,"navigation resumes after popup");}}
    check(owner.revision()==revision_before&&backend.writes[2]==1,"details are read-only and do not save");
    std::printf("editor frontend/handoff/modal: %u checks PASS\n",checks);return 0;
}
